function section(
  sectionCode: string,
  title: string,
  description: string,
  instructions: string,
  sortOrder: number,
  requiredEvidenceCategories: string[] = [],
  minimumContentExpectation: string | null = "Material section content must be present or the evidence gap must be explicitly stated.",
) {
  return {
    sectionCode,
    title,
    description,
    instructions,
    required: true,
    minimumContentExpectation,
    evidenceRequirements: requiredEvidenceCategories.length > 0
      ? { requiredEvidenceCategories, minimumEvidenceCount: 1 }
      : {},
    allowedSourceTypes: [
      "controlled_document",
      "participant_record",
      "service_delivery_record",
      "clinical_professional_document",
      "audit_record",
      "compliance_register",
      "regulatory_guidance",
      "regulator_correspondence",
      "employment_record",
      "payroll_record",
      "service_agreement",
      "task_upload",
    ],
    prohibitedAssumptions: [
      "Do not invent participant facts.",
      "Do not treat memory or user assertion as current approved evidence.",
      "Do not change clinical, BSP, RP or safeguarding meaning.",
    ],
    validationRules: [],
    qualityCriteria: [{ criterion: "participant_centred_traceable", description: "Content is participant-centred and traceable to evidence." }],
    sortOrder,
  };
}

function carePlanUserSection(
  sectionCode: string,
  title: string,
  description: string,
  instructions: string,
  sortOrder: number,
  requiredEvidenceCategories: string[] = [],
  minimumContentExpectation: string | null = "Section must be present. Conditional sections must contain content or explicit non-applicability naming the source.",
  extra?: Partial<ReturnType<typeof section>> & {
    fixedContent?: string[];
    fields?: string[];
    completionPrompt?: string | null;
    retrievalVocabulary?: {
      instrumentTerms?: string[];
      sourceSynonyms?: string[];
      accountableFields?: string[];
      controlledMappings?: Array<{ sourceValues: string[]; outputValue: string; rule?: string; terms?: string[] }>;
      nonApplicabilityTerms?: string[];
    };
  },
) {
  const base = section(sectionCode, title, description, instructions, sortOrder, requiredEvidenceCategories, minimumContentExpectation);
  const { retrievalVocabulary, evidenceRequirements: extraEvidenceRequirements, ...restExtra } = extra ?? {};
  return {
    ...base,
    sectionRole: "user_facing" as const,
    ...(restExtra ?? {}),
    evidenceRequirements: {
      ...base.evidenceRequirements,
      ...(extraEvidenceRequirements ?? {}),
      ...(retrievalVocabulary ? { retrievalVocabulary } : {}),
    },
  };
}

function authoredSheetSection(input: {
  sectionCode: string;
  title: string;
  existingProse: string;
  fixedContent: string;
  fields: string[];
  completionPrompt: string;
  sourceDocuments: string;
  mandatoryCondition: string;
  authorityBoundary: string;
  sortOrder: number;
  requiredEvidenceCategories: string[];
  optionalEvidenceCategories?: string[];
  excludedSourceDocuments?: Array<{ source: string; reason: string }>;
  unmappedSourceDocuments: string[];
}) {
  const base = section(
    input.sectionCode,
    input.title,
    input.existingProse,
    input.completionPrompt,
    input.sortOrder,
    input.requiredEvidenceCategories,
    null,
  );
  return {
    ...base,
    sectionRole: "user_facing" as const,
    fixedContent: [input.fixedContent],
    fields: input.fields,
    completionPrompt: input.completionPrompt,
    evidenceRequirements: {
      ...base.evidenceRequirements,
      sourceDocuments: input.sourceDocuments,
      mandatoryCondition: input.mandatoryCondition,
      authorityBoundary: input.authorityBoundary,
      optionalEvidenceCategories: input.optionalEvidenceCategories ?? [],
      excludedSourceDocuments: input.excludedSourceDocuments ?? [],
      unmappedSourceDocuments: input.unmappedSourceDocuments,
    },
  };
}

